    <div class="metric-grid">
      <button v-for="c in cards" :key="c.key" type="button" class="metric-card" :class="c.class" @click="active=c.key"><span>{{ c.label }}</span><strong>{{ summary[c.value] ?? 0 }}</strong><small>{{ c.caption }}</small></button>
    </div>
    <div class="quick-card"><div class="title-row"><div><h6>Menu Utama</h6><span>Akses cepat</span></div></div><div class="quick-grid"><button v-for="m in menus" :key="m.route" type="button" @click="go(m.route)"><i :class="['quick-icon',m.class,m.iconClass]"></i><span>{{ m.label }}</span></button></div></div>
