const router=useRouter();const active=ref('hadir')
const cards=[{key:'hadir',value:'hadir_hari_ini',label:'Hadir',caption:'Tercatat',class:'primary'},{key:'cuti',value:'cuti_hari_ini',label:'Cuti',caption:'Hari ini',class:'warning'},{key:'izin',value:'izin_hari_ini',label:'Izin',caption:'Hari ini',class:'info'},{key:'belum_absen',value:'belum_absen_hari_ini',label:'Belum Absen',caption:'Perlu perhatian',class:'danger'}]
const menus=[{label:'Kehadiran',route:'/kehadiran/presensi',iconClass:'blue',icon:'fas fa-fingerprint'},{label:'Cuti & Izin',route:'/kehadiran/cuti-izin',iconClass:'green',icon:'fas fa-calendar-plus'},{label:'Koreksi',route:'/kehadiran/koreksi',iconClass:'orange',icon:'fas fa-pen-to-square'},{label:'Lembur',route:'/kehadiran/lembur',iconClass:'purple',icon:'fas fa-business-time'},{label:'Rekap',route:'/kehadiran/rekap',iconClass:'cyan',icon:'fas fa-chart-column'},{label:'Persetujuan',route:'/kehadiran/persetujuan',iconClass:'red',icon:'fas fa-check-double'}]
const activeRows=computed(()=>props.summary[`${active.value}_hari_ini_data`]||[]);const activeLabel=computed(()=>cards.find(x=>x.key===active.value)?.label||'Data');const activeTitle=computed(()=>({hadir:'Pegawai Hadir',cuti:'Pegawai Cuti',izin:'Pegawai Izin',belum_absen:'Pegawai Belum Absen'})[active.value]||'Data Kehadiran');const activeClass=computed(()=>({hadir:'success',cuti:'warning',izin:'info',belum_absen:'danger'})[active.value]||'secondary');const go=p=>router.push(p);const compactLocation=(item)=>{const a=props.locationLabel(item,'masuk')?.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim()||'';const b=props.locationLabel(item,'pulang')?.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim()||'';return (a||b)?`<span><i class="fas fa-location-dot"></i> ${a}${a&&b?' · ':''}${b}</span>`:''}
</script>
